export const signupModeQueryKey = (options?: Options<SignupModeData>) => createQueryKey('signupMode', options);

/**
 * Read the sign-up mode of this site
 */
export const signupModeOptions = (options?: Options<SignupModeData>) => queryOptions<SignupModeResponse, SignupModeError, SignupModeResponse, ReturnType<typeof signupModeQueryKey>>({
    queryFn: async ({ queryKey, signal }) => {
        const { data } = await signupMode({
            ...options,
            ...queryKey[0],
            signal,
            throwOnError: true
        });
        return data;
    },
    queryKey: signupModeQueryKey(options)
});

/**
 * Create an account, then send a sign-in link with magicLinkSend
 */
export const signUpMutation = (options?: Partial<Options<SignUpData>>): UseMutationOptions<SignUpResponse, SignUpError, Options<SignUpData>> => {
    const mutationOptions: UseMutationOptions<SignUpResponse, SignUpError, Options<SignUpData>> = {
        mutationFn: async (fnOptions) => {
            const { data } = await signUp({
                ...options,
                ...fnOptions,
                throwOnError: true
            });
            return data;
        }
    };
    return mutationOptions;
};

/**
 * Vote on a post or a comment
 */
export const voteMutation = (options?: Partial<Options<VoteData>>): UseMutationOptions<VoteResponse, VoteError, Options<VoteData>> => {
    const mutationOptions: UseMutationOptions<VoteResponse, VoteError, Options<VoteData>> = {
        mutationFn: async (fnOptions) => {
            const { data } = await vote({
                ...options,
                ...fnOptions,
                throwOnError: true
            });
            return data;
        }
    };
    return mutationOptions;
};
